insert into public.ship_happens_settings(id,content) values ('main','{"title":"Ship Happens","start_date":"2026-10-05","end_date":"2026-11-01","total_days":28,"creator":"Tibo","handle":"thsottiaux","source_url":"https://x.com/thsottiaux/status/2106845241357824205","rule":"Each day, ship a clear improvement relevant to most Codex and Work users or deliver a full usage reset. A day can include multiple releases and a reset.","verified_at":"2026-10-06","reset_note":"Reset delivery requires an explicit source. Poll votes and missing updates do not confirm a reset."}'::jsonb) on conflict(id) do update set content=excluded.content;
