insert into public.ship_happens_releases(id,day,title,summary,category,source_url,product_url) values ('day-1-speed',1,'50% faster by default','Tibo announced approximately 50% faster default GPT-6 Astra and GPT-6.1 Sol subscription speed across products and partners using Sign in with ChatGPT. No changes needed from users.','Performance','https://x.com/thsottiaux/status/2107158998495748264',null) on conflict(id) do nothing;
insert into public.ship_happens_releases(id,day,title,summary,category,source_url,product_url) values ('day-2-auto-review',2,'Approve for me is free','Auto-review no longer consumes usage for users signed in through a ChatGPT account. Select Approve for me in the permissions menu.','Codex','https://x.com/thsottiaux/status/2107368734981517634',null) on conflict(id) do nothing;
insert into public.ship_happens_releases(id,day,title,summary,category,source_url,product_url) values ('day-2-api-tiers',2,'Simpler API tiers','Five paid usage tiers become Build, Launch, and Grow. The highest tier now requires $500 in total API payments, down from $1,000.','API','https://x.com/thsottiaux/status/2107548725359104441','https://x.com/i/status/2107539647392096384') on conflict(id) do nothing;
insert into public.ship_happens_releases(id,day,title,summary,category,source_url,product_url) values ('day-2-meetings',2,'Meetings get a note-taker','The Meetings plugin saves personalized meeting summaries and next steps in ChatGPT Space, giving Codex context for follow-up work.','ChatGPT','https://x.com/thsottiaux/status/2107573405553938664','https://x.com/i/status/2107567930557026653') on conflict(id) do nothing;
insert into public.ship_happens_releases(id,day,title,summary,category,source_url,product_url) values ('day-2-decisions',2,'Decisions API lands','The Decisions API is in public beta for all developers, helping apps choose a model, tool, or action in near real time.','API','https://x.com/thsottiaux/status/2107574912349303197','https://x.com/i/status/2107573382229188645') on conflict(id) do nothing;
